import { adminFetch } from "@/lib/admin-client";
import { uploadWithProgress, UploadError, type UploadProgress } from "@/lib/upload-client";
import { VIDEO_PART_BYTES, VIDEO_UPLOAD_MAX_BYTES, type MultipartUploadView } from "@/lib/video-upload-policy";

type Options = { file: File; courseSlug: string; lessonId: string; contentType: string; signal: AbortSignal;
  onProgress: (progress: UploadProgress) => void; onStatus: (message: string) => void; onSession?: (id: string) => void };
class ControlError extends Error { constructor(message: string, readonly status: number, readonly code?: string) { super(message); } }
async function wait(ms: number, signal: AbortSignal) {
  signal.throwIfAborted();
  await new Promise<void>((resolve, reject) => {
    const done = () => { signal.removeEventListener("abort", abort); resolve(); };
    const timer = setTimeout(done, ms);
    const abort = () => { clearTimeout(timer); signal.removeEventListener("abort", abort); reject(signal.reason); };
    signal.addEventListener("abort", abort, { once: true });
    if (signal.aborted) abort();
  });
}
async function control(payload: Record<string, unknown>, signal: AbortSignal) {
  for (let attempt = 0; ; attempt++) {
    signal.throwIfAborted();
    try {
      const response = await adminFetch("/api/admin/videos/multipart", { method: "POST", credentials: "same-origin", signal,
        headers: { "content-type": "application/json" }, body: JSON.stringify(payload) });
      const result = await response.json() as { error?: string; code?: string; upload?: MultipartUploadView; part?: { uploadUrl: string; headers: Record<string, string> } };
      if (!response.ok) throw new ControlError(result.error || "تعذر متابعة الرفع", response.status, result.code);
      return result;
    } catch (error) {
      if (signal.aborted || attempt >= 2 || error instanceof ControlError && (error.code === "MULTIPART_NOT_ENABLED" || error.status < 500 && error.status !== 429)) throw error;
      await wait(1000 * 2 ** attempt, signal);
    }
  }
}
function base64(bytes: ArrayBuffer) { return btoa(String.fromCharCode(...new Uint8Array(bytes))); }
async function manifest(options: Options) {
  const { file, signal, onStatus } = options, checksums: string[] = [];
  if (!file.size || file.size > VIDEO_UPLOAD_MAX_BYTES) throw new Error("حجم الفيديو غير مسموح.");
  for (let start = 0; start < file.size; start += VIDEO_PART_BYTES) {
    signal.throwIfAborted();
    onStatus(`جارٍ التحقق من بصمة الملف: ${Math.round(start / file.size * 100)}٪`);
    const bytes = await file.slice(start, start + VIDEO_PART_BYTES).arrayBuffer();
    checksums.push(base64(await crypto.subtle.digest("SHA-256", bytes)));
  }
  return checksums;
}
function saved(key: string): { requestId: string; sessionId?: string } | null {
  try { const value = JSON.parse(localStorage.getItem(key) || "null"); return typeof value?.requestId === "string" ? value : null; } catch { return null; }
}
function remember(key: string, value: { requestId: string; sessionId?: string }) { try { localStorage.setItem(key, JSON.stringify(value)); } catch { /* Resume within this invocation still works without browser storage. */ } }

export async function uploadResumableVideo(options: Options) {
  const { file, courseSlug, lessonId, contentType, signal, onProgress, onStatus } = options;
  const checksums = await manifest(options);
  const fingerprint = base64(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(JSON.stringify(checksums))));
  const cacheKey = `meras-video-upload-v1:${courseSlug}:${lessonId}:${contentType}:${file.size}:${fingerprint}`;
  let cache = saved(cacheKey) ?? { requestId: crypto.randomUUID() };
  remember(cacheKey, cache); // Write before the request: a lost start response must not create another upload.
  let upload: MultipartUploadView | undefined;
  try {
    upload = (await control({ action: "start", clientRequestId: cache.requestId, courseSlug, lessonId, contentType, sizeBytes: file.size, checksums }, signal)).upload;
  } catch (error) {
    if (error instanceof ControlError && error.code === "MULTIPART_NOT_ENABLED") return null;
    if (error instanceof ControlError && error.status === 410) {
      cache = { requestId: crypto.randomUUID() }; remember(cacheKey, cache);
      upload = (await control({ action: "start", clientRequestId: cache.requestId, courseSlug, lessonId, contentType, sizeBytes: file.size, checksums }, signal)).upload;
    } else throw error;
  }
  if (!upload?.id) throw new Error("الخادم لم يعطِ جلسة رفع صالحة.");
  remember(cacheKey, { ...cache, sessionId: upload.id }); options.onSession?.(upload.id);
  upload = (await control({ action: "status", id: upload.id }, signal)).upload;
  if (!upload) throw new Error("تعذر قراءة حالة الرفع.");
  if (upload.status === "uploading") {
    const completed = new Set(upload.completedParts), startedAt = performance.now();
    let loaded = [...completed].reduce((bytes, number) => bytes + Math.min(VIDEO_PART_BYTES, file.size - (number - 1) * VIDEO_PART_BYTES), 0);
    const alreadyUploaded = loaded;
    onStatus(completed.size ? `استئناف الرفع؛ ${completed.size} أجزاء محفوظة ولن تُرفع مجددًا.` : "جارٍ رفع الفيديو بأجزاء آمنة...");
    for (let partNumber = 1; partNumber <= checksums.length; partNumber++) {
      if (completed.has(partNumber)) continue;
      const part = file.slice((partNumber - 1) * VIDEO_PART_BYTES, partNumber * VIDEO_PART_BYTES);
      for (let attempt = 0; ; attempt++) {
        signal.throwIfAborted();
        const signed = (await control({ action: "sign", id: upload.id, partNumber }, signal)).part;
        if (!signed?.uploadUrl) throw new Error("تعذر توقيع جزء الرفع.");
        try {
          await uploadWithProgress({ url: signed.uploadUrl, method: "PUT", body: part, headers: signed.headers,
            withCredentials: false, timeoutMs: 10 * 60_000, signal, onProgress: progress => {
              const current = Math.min(file.size, loaded + progress.loaded);
              const speed = Math.max(0, current - alreadyUploaded) / Math.max(0.1, (performance.now() - startedAt) / 1000);
              onProgress({ loaded: current, total: file.size, percent: Math.round(current / file.size * 100), bytesPerSecond: speed,
                remainingSeconds: speed > 0 ? Math.ceil((file.size - current) / speed) : null });
            } });
          loaded += part.size; break;
        } catch (error) {
          if (signal.aborted || attempt >= 2 || error instanceof UploadError && error.status >= 400 && error.status < 500 && ![403, 408, 429].includes(error.status)) throw error;
          onStatus(`إعادة محاولة الجزء ${partNumber} فقط؛ الأجزاء المكتملة محفوظة.`);
          await wait(1000 * 2 ** attempt, signal);
        }
      }
    }
    onStatus("جارٍ التحقق من جميع الأجزاء واعتماد الملف...");
    upload = (await control({ action: "complete", id: upload.id }, signal)).upload;
    if (!upload) throw new Error("لم يؤكد الخادم اكتمال الرفع.");
  }
  return { ...upload, forget: () => { try { localStorage.removeItem(cacheKey); } catch { /* no-op */ } } };
}

export async function discardResumableVideoUpload(id: string, signal: AbortSignal) {
  await control({ action: "abort", id }, signal);
}
